// Stats reads the store state in dir without modifying it and reports
// the number of live keys, the cumulative number of successfully taken
// snapshots, and the average length of live values. It returns (0, 0, 0)
// when no keys are live.
func Stats(dir string) (keys int, snapshots uint64, avgBytes float64, err error) {
	fi, err := os.Stat(dir)
	if err != nil {
		return 0, 0, 0, fmt.Errorf("snapshot: stats %s: %w", dir, err)
	}
	if !fi.IsDir() {
		return 0, 0, 0, fmt.Errorf("snapshot: stats %s: not a directory: %w", dir, fs.ErrInvalid)
	}
	f, err := os.Open(filepath.Join(dir, walName))
	if errors.Is(err, fs.ErrNotExist) {
		return 0, 0, 0, nil
	}
	if err != nil {
		return 0, 0, 0, fmt.Errorf("snapshot: stats %s: %w", dir, err)
	}
	defer f.Close()

	live, snaps, _, err := replayFrom(f)
	if err != nil {
		return 0, 0, 0, err
	}
	var total uint64
	for _, v := range live {
		total += uint64(len(v))
	}
	avg := 0.0
	if len(live) > 0 {
		avg = float64(total) / float64(len(live))
	}
	return len(live), snaps, avg, nil
}

