// Command snapshotctl inspects a snapshot-kv store directory.
//
//	snapshotctl --dir <path> stats
//
// stats prints one compact JSON line:
//
//	{"keys":N,"snapshots":M,"avgBytes":X.XX}
//
// and exits 1 without printing anything if the directory cannot be
// opened.
package main

import (
	"flag"
	"fmt"
	"os"

	snapshot "github.com/Hulalalalalalalalalalala/snapshot-kv"
)

func main() {
	dir := flag.String("dir", "", "store directory")
	flag.Parse()
	args := flag.Args()
	if len(args) != 1 || args[0] != "stats" || *dir == "" {
		fmt.Fprintln(os.Stderr, "usage: snapshotctl --dir <path> stats")
		os.Exit(2)
	}

	keys, snaps, avg, err := snapshot.Stats(*dir)
	if err != nil {
		os.Exit(1)
	}
	fmt.Printf("{\"keys\":%d,\"snapshots\":%d,\"avgBytes\":%s}\n",
		keys, snaps, formatAvg(avg))
}

// formatAvg renders a non-negative average with exactly two decimals,
// rounded half away from zero. Integer math keeps it free of negative
// zero, NaN and Inf.
func formatAvg(avg float64) string {
	if avg <= 0 {
		return "0.00"
	}
	cents := uint64(avg*100 + 0.5)
	return fmt.Sprintf("%d.%02d", cents/100, cents%100)
}

